from abc import ABC, abstractmethodfrom typing import Callable, List, Optionalimport jaximport jax.numpy as npfrom ..transforms import Transformclass Topology(ABC):    """Base class for topology optimization problems"""        def __init__(self, problem, x, transform: Transform,                   obj: Callable, cons: List[Callable],                  info: Optional[dict] = None):        self.problem = problem        self.element_volume = np.sum(problem.fes[0].JxW, axis=1, keepdims=True)        self.domain_volume = np.sum(self.element_volume)                self.transform = transform          self.obj = obj        self.cons = cons        self.info = info or {}                # Pre-define functions with value_and_grad        self._define_functions_with_gradients()                # Initialize state        self.num_x = len(x)        self.update(x)        def _define_functions_with_gradients(self):        """Define functions that compute both value and gradient"""                def objective_with_transforms(x):            x_phys = self.transform(x)              return self.obj(x_phys)                self._objective_value_and_grad = jax.value_and_grad(objective_with_transforms)                self._constraint_value_and_grad_fns = []        for cons_fn in self.cons:            def make_constraint_function(fn):                def constraint_with_transforms(x):                    x_phys = self.transform(x)                    return fn(x_phys)                return constraint_with_transforms                        constraint_fn = make_constraint_function(cons_fn)            self._constraint_value_and_grad_fns.append(jax.value_and_grad(constraint_fn))        def _reset_evaluation(self):        """Reset evaluation results to None"""        self.J = None        self.dJ = None        self.c = None        self.dc = None        self._evaluation_valid = False        def update(self, xnew):        """Update design variables and clear evaluation results"""        self.x = xnew        self.xPhys = self.transform(xnew)          self._reset_evaluation()        def evaluate(self):        """Evaluate objective and constraints (cached)"""        if not self._evaluation_valid:            # Compute objective value and gradient            self.J, self.dJ = self._objective_value_and_grad(self.x)                        # Compute constraint values and gradients            self.c = []            self.dc = []            for constraint_value_grad_fn in self._constraint_value_and_grad_fns:                c_val, c_grad = constraint_value_grad_fn(self.x)                self.c.append(c_val)                self.dc.append(c_grad)                        self._evaluation_valid = True                return self.J, self.dJ, self.c, self.dc        def update_and_evaluate(self, xnew):        """Update design variables and evaluate in one call"""        self.update(xnew)        return self.evaluate()        def get_intermediate_values(self):        """Compute and return all intermediate values"""        if hasattr(self.transform, 'transforms') and hasattr(self.transform.transforms, '__iter__'):            x0 = self.x.copy()            intermediate_values = [x0]            current = x0                        for transform in self.transform.transforms:                current = transform(current)                intermediate_values.append(current.copy())                        return tuple(intermediate_values)        else:            x0 = self.x.copy()            x1 = self.xPhys.copy()            return x0, x1        @abstractmethod    def compute_volume_fraction(self):        """Compute volume fraction for current design - to be implemented by subclasses"""        pass        @property    def design_variables(self):        return self.x        @property    def physical_field(self):        return self.xPhys        @property    def evaluation_valid(self):        """Check if evaluation results are up-to-date"""        return self._evaluation_valid    